package tools.php.ast2cpg;
import java.io.*; import java.util.*; import ast.php.functionDef.FunctionDef; import inputModules.csv.csvFuncExtractor.CSVFunctionExtractor; import cg.*; import cfg.*; import udg.*; import udg.php.useDefAnalysis.PHPASTDefUseAnalyzer; import udg.useDefGraph.UseDefGraph; import ddg.*; import ddg.DataDependenceGraph.DDG; import ddg.DefUseCFG.DefUseCFG;
public class ProbeCG { public static void main(String[] args)throws Exception{ Main.baseDir="."; CSVFunctionExtractor ex=new CSVFunctionExtractor(); ex.setInterpreters(new PHPCSVNodeInterpreter(),new PHPCSVEdgeInterpreter()); ex.initialize(new FileReader("nodes.csv"),new FileReader("rels.csv")); ASTToCFGConverter a=new ASTToCFGConverter(); a.setFactory(new PHPCFGFactory()); CFGToUDGConverter b=new CFGToUDGConverter(); b.setASTDefUseAnalyzer(new PHPASTDefUseAnalyzer()); CFGAndUDGToDefUseCFG c=new CFGAndUDGToDefUseCFG(); DDGCreator d=new DDGCreator(); HashSet<FunctionDef> roots=new HashSet<>(); FunctionDef r; while((r=(FunctionDef)ex.getNextFunction())!=null){roots.add(r); CFG cfg=a.convert(r); UseDefGraph u=b.convert(cfg); DefUseCFG du=c.convert(cfg,u); d.createForDefUseCFG(du);} for(FunctionDef root:roots)PHPCGFactory.addFunctionDef(root); PHPCGFactory.newInstance(); System.out.println("ROOTS="+roots.size()); for(Long k:new TreeSet<Long>(PHPCGFactory.call2mtd.keySet()))System.out.println("EDGE "+k+" -> "+PHPCGFactory.call2mtd.get(k)); }}
